import numpy as np, os, re
from collections import Counter, deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(I, minsize=4):
    I=np.array(I); H,W=I.shape
    bg=Counter(I.flat).most_common(1)[0][0]
    out=bg*np.ones((H,W),int)
    seen=set()
    for r in range(H):
        for c in range(W):
            v=I[r][c]
            if v!=bg and (r,c) not in seen:
                q=deque([(r,c)]); comp=[]; seen.add((r,c))
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==v and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                rs=[p[0] for p in comp]; cc=[p[1] for p in comp]
                if len(comp)>=minsize:
                    r0,r1=min(rs),max(rs); c0,c1=min(cc),max(cc)
                    for rr in range(r0,r1+1):
                        for xx in range(c0,c1+1):
                            out[rr][xx]=v
    return out.tolist()
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    for ms in [1,2,3,4,5]:
        ok = f(G[name+' input'],ms)==G[name+' output']
        print(name,'minsize',ms,'ok' if ok else 'FAIL')

